import numpy as np
f=np.load('source_pixels.npz')['rgb'].astype(int)
for i in [1,5,10,14,15,16,20,25,29,30,31,32,35,40,45,48,49]:
 d=np.max(abs(f[i]-f[i-1]),2); m=d>10
 a=f[i][m]; prev=f[i-1][m]
 def stats(a):
  if not len(a):return''
  R,G,B=a.T
  labs={'blue':(B>R+15)&(B>G+8),'red':(R>G+20)&(R>B+15),'yellow':(R>B+15)&(G>B+10),'dark':a.mean(1)<80,'bright':a.mean(1)>170}
  return ' '.join(f'{k}:{v.sum()}' for k,v in labs.items())+' mean'+str(np.round(a.mean(0),1))
 print(i,'n',m.sum(),'old',stats(prev),'new',stats(a))
PY"
